/**
 * Decodes a base64 string to a Uint8Array in any JavaScript environment (browser or Node).
 */
export function decodeBase64ToUint8Array(base64: string): Uint8Array {
  if (typeof atob === "function") {
    const binStr = atob(base64);
    const len = binStr.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
      bytes[i] = binStr.charCodeAt(i);
    }
    return bytes;
  }
  // Node.js fallback
  return new Uint8Array(Buffer.from(base64, "base64"));
}

export function getSampleWorkbookBytes(id: string): { bytes: Uint8Array; meta: SampleWorkbookMeta } {
  const found = SAMPLE_WORKBOOKS.find((s) => s.id === id);
  if (!found) {
    throw new Error('Sample workbook with id "' + id + '" not found');
  }
  return { bytes: decodeBase64ToUint8Array(found.base64), meta: found };
}
